package i18n

import "strings"

// NativeText translates presentation-owned copy only. Stable IDs, entered
// names, enum payloads and technical definitions must never pass through it.
func (l Localizer) NativeText(value string) string {
	if l.Locale() != Persian {
		return value
	}
	if translated := nativePersian[value]; translated != "" {
		return translated
	}
	if translated := nativePersianFolded[strings.ToLower(value)]; translated != "" {
		return translated
	}
	for _, prefix := range []string{"Sequence editor · ", "Programs & effects · "} {
		if strings.HasPrefix(value, prefix) {
			return l.NativeText(strings.TrimSuffix(prefix, " · ")) + " · " + strings.TrimPrefix(value, prefix)
		}
	}
	return value
}

